def cAPS_lOCK(string):
    if string.isupper():
        return string.lower()
    elif len(string) > 1 and string[1:].isupper() and string[0].islower():
        return string[0].upper() + string[1:].lower()
    elif len(string) == 1:
        return string.upper()
    else:
        return string

