class Solution:
	def __init__(self):
		pass

	def solve(self):
		s = input()
		string = ""

		if s.isupper():
			string = s.lower()
		elif s[1:].isupper() and s[0].islower():
			string = s[0].upper() + s[1:].lower()
		elif len(s) == 1:
			string = s.swapcase()
		else:
			string = s

		print(string)

if __name__ == "__main__":
	sol = Solution()
	sol.solve()

